39         public byte[] Read(string storedPath)
40         {
41             if (string.IsNullOrWhiteSpace(storedPath))
42             {
43                 throw new ArgumentException("Caminho do anexo ausente.");
44             }
45 
46             var root = Path.GetFullPath(RootPath());
47             var separator = Path.DirectorySeparatorChar.ToString();
48             if (!root.EndsWith(separator, StringComparison.OrdinalIgnoreCase))
